using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.IO;
using System.Windows.Forms;
namespace ZenForms.Core
{
    public sealed class ZenDiffSummaryEventArgs : EventArgs { public int Added { get; private set; } public int Removed { get; private set; } public int Unchanged { get; private set; } public ZenDiffSummaryEventArgs(int a, int r, int u) { Added = a; Removed = r; Unchanged = u; } }
    [Category("ZenForms Modern Components")]
    [Description("Text comparer table.")]
    public class ZenDiffViewer : UserControl
    {
        private readonly RichTextBox left, right; private readonly Label summary; private string leftText = "", rightText = ""; private int added, removed, unchanged;
        [Category("ZenForms Diff")] public string LeftText { get { return leftText; } set { leftText = value ?? ""; Compare(); } }
        [Category("ZenForms Diff")] public string RightText { get { return rightText; } set { rightText = value ?? ""; Compare(); } }
        public event EventHandler<ZenDiffSummaryEventArgs> ComparisonCompleted;
        public ZenDiffViewer() { Size = new Size(800, 480); BackColor = ZenTheme.Background; Panel toolbar = new Panel { Dock = DockStyle.Top, Height = 38, BackColor = ZenTheme.Surface }; Button openLeft = MakeButton("Open Left", 110), openRight = MakeButton("Open Right", 110), compare = MakeButton("Compare", 86); summary = new Label { Dock = DockStyle.Fill, Text = "Choose or paste two texts", ForeColor = ZenTheme.Muted, TextAlign = ContentAlignment.MiddleRight, Padding = new Padding(0, 0, 10, 0) }; FlowLayoutPanel actions = new FlowLayoutPanel { Dock = DockStyle.Left, Width = 320, WrapContents = false }; actions.Controls.Add(openLeft); actions.Controls.Add(openRight); actions.Controls.Add(compare); toolbar.Controls.Add(summary); toolbar.Controls.Add(actions); SplitContainer split = new SplitContainer { Dock = DockStyle.Fill, BackColor = ZenTheme.Border, SplitterWidth = 4, Panel1MinSize = 80, Panel2MinSize = 80 }; left = MakeEditor(); right = MakeEditor(); split.Panel1.Controls.Add(left); split.Panel2.Controls.Add(right); Controls.Add(split); Controls.Add(toolbar); openLeft.Click += (s, e) => LoadFile(true); openRight.Click += (s, e) => LoadFile(false); compare.Click += (s, e) => { leftText = left.Text; rightText = right.Text; Compare(); }; left.TextChanged += (s, e) => leftText = left.Text; right.TextChanged += (s, e) => rightText = right.Text; }
        public void SetTexts(string before, string after) { leftText = before ?? ""; rightText = after ?? ""; left.Text = leftText; right.Text = rightText; Compare(); }
        public void Compare() { if (left == null || right == null) return; leftText = left.Text; rightText = right.Text; string[] a = leftText.Replace("\r\n", "\n").Split('\n'), b = rightText.Replace("\r\n", "\n").Split('\n'); List<Row> rows = BuildRows(a, b); added = removed = unchanged = 0; left.SuspendLayout(); right.SuspendLayout(); left.Clear(); right.Clear(); foreach (Row row in rows) { Append(left, row.Left, row.Kind == Kind.Removed ? Color.FromArgb(58, 53, 68) : Color.FromArgb(13, 17, 29), row.Kind == Kind.Removed ? ZenTheme.Danger : ZenTheme.Foreground); Append(right, row.Right, row.Kind == Kind.Added ? Color.FromArgb(36, 91, 73) : Color.FromArgb(13, 17, 29), row.Kind == Kind.Added ? ZenTheme.Accent : ZenTheme.Foreground); if (row.Kind == Kind.Added) added++; else if (row.Kind == Kind.Removed) removed++; else unchanged++; } left.ResumeLayout(); right.ResumeLayout(); summary.Text = String.Format("+{0} addeds     −{1} removeds     ={2} equals", added, removed, unchanged); EventHandler<ZenDiffSummaryEventArgs> h = ComparisonCompleted; if (h != null) h(this, new ZenDiffSummaryEventArgs(added, removed, unchanged)); }
        private static List<Row> BuildRows(string[] a, string[] b) { List<Row> rows = new List<Row>(); if ((long)a.Length * b.Length > 1500000) { int max = Math.Max(a.Length, b.Length); for (int i = 0; i < max; i++) { string x = i < a.Length ? a[i] : null, y = i < b.Length ? b[i] : null; if (x == y) rows.Add(new Row(x, y, Kind.Same)); else { if (x != null) rows.Add(new Row(x, "", Kind.Removed)); if (y != null) rows.Add(new Row("", y, Kind.Added)); } } return rows; } int n = a.Length, m = b.Length; int[,] lcs = new int[n + 1, m + 1]; for (int i = n - 1; i >= 0; i--) for (int j = m - 1; j >= 0; j--) lcs[i, j] = a[i] == b[j] ? lcs[i + 1, j + 1] + 1 : Math.Max(lcs[i + 1, j], lcs[i, j + 1]); int x0 = 0, y0 = 0; while (x0 < n || y0 < m) { if (x0 < n && y0 < m && a[x0] == b[y0]) { rows.Add(new Row(a[x0], b[y0], Kind.Same)); x0++; y0++; } else if (y0 < m && (x0 == n || lcs[x0, y0 + 1] >= lcs[x0 + 1, y0])) { rows.Add(new Row("", b[y0++], Kind.Added)); } else rows.Add(new Row(a[x0++], "", Kind.Removed)); } return rows; }
        private static void Append(RichTextBox box, string text, Color back, Color fore) { int start = box.TextLength; box.AppendText((text ?? "") + Environment.NewLine); box.Select(start, box.TextLength - start); box.SelectionBackColor = back; box.SelectionColor = fore; box.Select(box.TextLength, 0); }
        private void LoadFile(bool isLeft) { using (OpenFileDialog d = new OpenFileDialog { Filter = "Text|*.txt;*.cs;*.json;*.xml;*.md;*.log|All Files|*.*" }) if (d.ShowDialog(FindForm()) == DialogResult.OK) { if (isLeft) left.Text = File.ReadAllText(d.FileName); else right.Text = File.ReadAllText(d.FileName); leftText = left.Text; rightText = right.Text; Compare(); } }
        private static Button MakeButton(string text, int width) { return new Button { Text = text, Width = width, Height = 28, FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground, Font = new Font("Segoe UI", 8f), Margin = new Padding(2, 4, 2, 2) }; }
        private static RichTextBox MakeEditor() { return new RichTextBox { Dock = DockStyle.Fill, BorderStyle = BorderStyle.None, BackColor = Color.FromArgb(13, 17, 29), ForeColor = ZenTheme.Foreground, Font = new Font("Consolas", 9f), WordWrap = false, AcceptsTab = true, HideSelection = false }; }
        private enum Kind { Same, Added, Removed }
        private sealed class Row { public string Left, Right; public Kind Kind; public Row(string l, string r, Kind k) { Left = l; Right = r; Kind = k; } }
    }
}
